targets.expr:
label_replace(
count by(instance) (
  count by(instance, cpu) (
    node_cpu_seconds_total{dc="$job", bare_metal="false", k8s!="true", mode="idle"}
  )
)
* on(instance) group_left(nodename)
node_uname_info{dc="$job", bare_metal="false", k8s!="true"},
"hostname",
"$1",
"nodename",
"(.*)"
)

label_replace(
100 * (1 - (
  node_memory_MemAvailable_bytes{dc="$job", bare_metal="false", k8s!="true"}
  /
  node_memory_MemTotal_bytes{dc="$job", bare_metal="false", k8s!="true"}
))
* on(instance) group_left(nodename)
node_uname_info{dc="$job", bare_metal="false", k8s!="true"},
"hostname",
"$1",
"nodename",
"(.*)"
)

count(
  node_uname_info{bare_metal="false"}
  and on(instance)
  node_uname_info{instance=~"$node", bare_metal="false"}
)

count by(instance) (
  node_cpu_seconds_total{dc=~"$job", instance=~"$node", mode="idle"}
)

100 *
(
  node_load1{instance=~"$node", dc=~"$job"}
/
on(instance) group_left
count by(instance)(
  node_cpu_seconds_total{instance=~"$node", dc=~"$job", mode="idle"}
)
)

avg by(instance) (
  rate(node_pressure_cpu_waiting_seconds_total{instance=~"$node", dc=~"$job"}[$__rate_interval])
) * 100

avg by(instance) (
  rate(node_pressure_memory_waiting_seconds_total{instance=~"$node", dc=~"$job"}[$__rate_interval])
) * 100

sum by(instance) (
  rate(node_network_receive_bytes_total{instance=~"$node", dc=~"$job", device!~"lo"}[$__rate_interval])
)

sum by(instance) (
  rate(node_network_transmit_bytes_total{instance=~"$node", dc=~"$job", device!~"lo"}[$__rate_interval])
)

max by(instance) (
  node_filesystem_size_bytes{instance=~"$node", dc=~"$job", mountpoint="/", fstype!=""}
)

max by(instance) (
  node_filesystem_avail_bytes{instance=~"$node", dc=~"$job", mountpoint="/", fstype!=""}
)

max by(instance) (
  node_filesystem_size_bytes{instance=~"$node", dc=~"$job", mountpoint="/", fstype!=""}
)
-
max by(instance) (
  node_filesystem_avail_bytes{instance=~"$node", dc=~"$job", mountpoint="/", fstype!=""}
)

avg by(instance) (
  rate(node_pressure_io_waiting_seconds_total{instance=~"$node", dc=~"$job"}[$__rate_interval])
) * 100
